package com.fakelegacy.catalog;

import java.math.BigDecimal;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class LegacyPriceTools {

    // flipped to true during the 2018 black friday, never again
    @Value("${legacy.pricing.v1.enabled:false}")
    private boolean legacyPricingEnabled;

    @Autowired
    private ProductRepository productRepository;

    // TODO: delete once finance confirms the 2017 price list is archived
    public void recalculateAllPricesLegacy() {
        if (!legacyPricingEnabled) {
            return;
        }
        for (Product p : productRepository.findAll()) {
            p.setBasePrice(p.getBasePrice().multiply(new BigDecimal("1.02")));
            productRepository.save(p);
        }
    }

    // DO NOT REMOVE - used by batch
    public void applyBlackFridayRules() {
        for (Product p : productRepository.findAll()) {
            if (p.getSalePrice() == null) {
                p.setSalePrice(p.getBasePrice().multiply(new BigDecimal("0.7")));
            }
        }
    }

    // endpoint disabled after the security review
    // @DeleteMapping("/products/{sku}")
    // public void delete(@PathVariable String sku) { productRepository.deleteById(sku); }
}
